examples.code:
{
  "response_headers_baseline": {
    "Strict-Transport-Security": "max-age=31536000; includeSubDomains",
    "X-Content-Type-Options": "nosniff",
    "Content-Security-Policy": "default-src 'self'; frame-ancestors 'none'; upgrade-insecure-requests",
    "Referrer-Policy": "strict-origin-when-cross-origin",
    "Permissions-Policy": "camera=(), microphone=(), geolocation=()"
  },
  "log_events": {
    "auth.login.success": { "fields": ["userId", "ip", "userAgent", "correlationId"] },
    "auth.login.failure": { "fields": ["emailHash", "reason", "ip", "correlationId"] },
    "authz.denied": { "fields": ["userId", "action", "resourceType", "correlationId"] },
    "admin.user.delete": { "fields": ["actorId", "targetUserId", "correlationId"] }
  },
  "never_logged": [
    "passwords (plain or hashed)",
    "session tokens / JWTs",
    "cookies and Authorization headers",
    "full payment card numbers",
    "government identifiers"
  ],
  "redaction_note": "Request bodies are redacted at the logging middleware by default; allowlisted fields must be added explicitly per endpoint."
}
